diff --git a/src/main/java/hotel/reservations/FinanceNotifier.java b/src/main/java/hotel/reservations/FinanceNotifier.java
new file mode 100644
index 0000000..8806678
--- /dev/null
+++ b/src/main/java/hotel/reservations/FinanceNotifier.java
@@ -0,0 +1,37 @@
+package hotel.reservations;
+
+import hotel.documents.TextFormat;
+import hotel.messages.EmailSender;
+import java.math.BigDecimal;
+
+/** Notifies finance about payments received and refunds due. */
+public final class FinanceNotifier implements ReservationListener {
+
+    private static final String FINANCE_EMAIL = "financeiro@pousadamarealta.com.br";
+
+    private final EmailSender emailSender;
+
+    public FinanceNotifier(EmailSender emailSender) {
+        this.emailSender = emailSender;
+    }
+
+    @Override
+    public void onReservationConfirmed(Reservation reservation) {
+        String subject = "Pagamento recebido - reserva " + reservation.id();
+        String body = "Um pagamento foi recebido:\n\n"
+                + "Reserva: " + reservation.id() + "\n"
+                + "Valor: " + TextFormat.money(reservation.amountPaid()) + "\n";
+        emailSender.send(FINANCE_EMAIL, subject, body);
+    }
+
+    @Override
+    public void onReservationCancelled(Reservation reservation) {
+        if (reservation.refund() != null && reservation.refund().compareTo(BigDecimal.ZERO) > 0) {
+            String subject = "Reembolso - reserva " + reservation.id();
+            String body = "Um reembolso precisa ser processado:\n\n"
+                    + "Reserva: " + reservation.id() + "\n"
+                    + "Valor: " + TextFormat.money(reservation.refund()) + "\n";
+            emailSender.send(FINANCE_EMAIL, subject, body);
+        }
+    }
+}
diff --git a/src/main/java/hotel/reservations/HousekeepingNotifier.java b/src/main/java/hotel/reservations/HousekeepingNotifier.java
new file mode 100644
index 0000000..9486663
--- /dev/null
+++ b/src/main/java/hotel/reservations/HousekeepingNotifier.java
@@ -0,0 +1,38 @@
+package hotel.reservations;
+
+import hotel.documents.TextFormat;
+import hotel.messages.EmailSender;
+
+/** Notifies housekeeping when rooms need to be prepared or freed up. */
+public final class HousekeepingNotifier implements ReservationListener {
+
+    private static final String HOUSEKEEPING_EMAIL = "governanca@pousadamarealta.com.br";
+
+    private final EmailSender emailSender;
+
+    public HousekeepingNotifier(EmailSender emailSender) {
+        this.emailSender = emailSender;
+    }
+
+    @Override
+    public void onReservationConfirmed(Reservation reservation) {
+        String subject = "Reserva confirmada - quarto " + reservation.roomNumber();
+        String body = "Uma reserva foi confirmada:\n\n"
+                + "Quarto: " + reservation.roomNumber() + "\n"
+                + "Entrada: " + TextFormat.date(reservation.checkIn()) + "\n"
+                + "Saída: " + TextFormat.date(reservation.checkOut()) + "\n"
+                + "Hóspedes: " + reservation.guests() + "\n";
+        emailSender.send(HOUSEKEEPING_EMAIL, subject, body);
+    }
+
+    @Override
+    public void onReservationCancelled(Reservation reservation) {
+        String subject = "Reserva cancelada - quarto " + reservation.roomNumber();
+        String body = "Uma reserva foi cancelada:\n\n"
+                + "Quarto: " + reservation.roomNumber() + "\n"
+                + "Entrada: " + TextFormat.date(reservation.checkIn()) + "\n"
+                + "Saída: " + TextFormat.date(reservation.checkOut()) + "\n"
+                + "\nO quarto está disponível novamente para essas datas.\n";
+        emailSender.send(HOUSEKEEPING_EMAIL, subject, body);
+    }
+}
diff --git a/src/main/java/hotel/reservations/ReservationListener.java b/src/main/java/hotel/reservations/ReservationListener.java
new file mode 100644
index 0000000..03646f7
--- /dev/null
+++ b/src/main/java/hotel/reservations/ReservationListener.java
@@ -0,0 +1,14 @@
+package hotel.reservations;
+
+/**
+ * Receives notifications when important reservation events happen. Departments can subscribe to be
+ * notified about confirmations, cancellations, and other events they care about.
+ */
+public interface ReservationListener {
+
+    /** A pending reservation was confirmed: the guest paid and the room is theirs. */
+    void onReservationConfirmed(Reservation reservation);
+
+    /** A confirmed reservation was cancelled: the room is now available again. */
+    void onReservationCancelled(Reservation reservation);
+}
