    10	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    11	public final class ReservationService {
    12	
    13	    static final String HOTEL_NAME = "Pousada Maré Alta";
    14	
    15	    private final Rooms rooms;
    16	    private final ReservationStore store;
    17	    private final PriceCalculator priceCalculator;
    18	    private final EmailSender emailSender;
    19	    private final List<ReservationListener> listeners;
    20	
    21	    public ReservationService(
    22	            Rooms rooms,
    23	            ReservationStore store,
    24	            PriceCalculator priceCalculator,
    25	            EmailSender emailSender,
    26	            List<ReservationListener> listeners) {
    27	        this.rooms = rooms;
    28	        this.store = store;
    29	        this.priceCalculator = priceCalculator;
    30	        this.emailSender = emailSender;
    31	        this.listeners = listeners;
    32	    }
    33	
    34	    public synchronized Reservation create(NewReservation request) {
    35	        if (!request.checkOut().isAfter(request.checkIn())) {
    36	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    37	        }
    38	        if (request.guests() < 1) {
    39	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    40	        }
    41	        Room room = rooms.find(request.roomNumber())
    42	                .orElseThrow(() -> new HotelException(
    43	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    44	        if (request.guests() > room.capacity()) {
    45	            throw new HotelException(
    46	                    ErrorCode.CAPACITY_EXCEEDED,
    47	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    48	        }
    49	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    50	            throw new HotelException(
    51	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    52	        }
    53	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    54	        return store.add(request, price);
    55	    }
    56	
    57	    public Reservation find(long reservationId) {
    58	        return store.find(reservationId)
    59	                .orElseThrow(() -> new HotelException(
    60	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    61	    }
    62	
    63	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    64	    public synchronized Reservation confirm(long reservationId) {
    65	        Reservation reservation = find(reservationId);
    66	        if (reservation.status() != ReservationStatus.PENDING) {
    67	            throw notAllowed(reservation, "confirm");
    68	        }
    69	        reservation.confirmPayment();
    70	        store.update(reservation);
    71	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    72	        emailSender.send(
    73	                reservation.guest().email(),
    74	                "Reserva confirmada - " + HOTEL_NAME,
    75	                confirmationEmailBody(reservation, receipt));
    76	        for (ReservationListener listener : listeners) {
    77	            listener.onReservationConfirmed(reservation);
    78	        }
    79	        return reservation;
    80	    }
    81	
    82	    /**
    83	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    84	     * reservation was never paid, so nothing comes back).
    85	     */
    86	    public synchronized Reservation cancel(long reservationId) {
    87	        Reservation reservation = find(reservationId);
    88	        if (reservation.status() != ReservationStatus.PENDING
    89	                && reservation.status() != ReservationStatus.CONFIRMED) {
    90	            throw notAllowed(reservation, "cancel");
    91	        }
    92	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    93	        BigDecimal refund = switch (reservation.ratePlan()) {
    94	            case STANDARD -> reservation.amountPaid();
    95	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    96	        };
    97	        reservation.cancel(refund);
    98	        store.update(reservation);
    99	        if (wasConfirmed) {
   100	            for (ReservationListener listener : listeners) {
   101	                listener.onReservationCancelled(reservation);
   102	            }
   103	        }
   104	        return reservation;
   105	    }
   106	
   107	    public synchronized Reservation checkIn(long reservationId) {
   108	        Reservation reservation = find(reservationId);
   109	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   110	            throw notAllowed(reservation, "check in");
   111	        }
   112	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   113	        store.update(reservation);
   114	        return reservation;
   115	    }
   116	
   117	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   118	    public synchronized ReservationReceipt checkOut(long reservationId) {
   119	        Reservation reservation = find(reservationId);
   120	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   121	            throw notAllowed(reservation, "check out");
   122	        }
   123	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   124	        store.update(reservation);
   125	        return new ReservationReceipt(reservation, roomOf(reservation));
   126	    }
   127	
   128	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   129	    public ReservationReceipt receiptCopy(long reservationId) {
   130	        Reservation reservation = find(reservationId);
   131	        if (!reservation.isPaid()) {
   132	            throw notAllowed(reservation, "issue a receipt for");
   133	        }
   134	        return new ReservationReceipt(reservation, roomOf(reservation));
   135	    }
   136	
   137	    private Room roomOf(Reservation reservation) {
   138	        return rooms.find(reservation.roomNumber()).orElseThrow();
   139	    }
   140	
   141	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   142	        return "Olá, " + reservation.guest().name() + "!\n\n"
   143	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   144	                + receipt.text() + "\n"
   145	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   146	                + "Até breve!\n";
   147	    }
   148	
   149	    private static HotelException notAllowed(Reservation reservation, String operation) {
   150	        return new HotelException(
   151	                ErrorCode.OPERATION_NOT_ALLOWED,
   152	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   153	    }
   154	}
