   173	/** Puts the inn's pieces together and runs the HTTP server. */
   174	public final class Hotel {
   175	
   176	    private final Javalin server;
   177	
   178	    public Hotel(DataSource dataSource) {
   179	        Rooms rooms = new Rooms(dataSource);
   180	        ReservationStore store = new ReservationStore(dataSource);
   181	        SentMessages sentMessages = new SentMessages(dataSource);
   182	        EmailSender emailSender = new EmailSender(sentMessages);
   183	        List<ReservationListener> listeners =
   184	                List.of(new HousekeepingNotifier(emailSender), new FinanceNotifier(emailSender));
   185	        ReservationService reservations =
   186	                new ReservationService(rooms, store, new PriceCalculator(), emailSender, listeners);
   187	        HttpApi api = new HttpApi(
   188	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
   189	        this.server = api.server();
   190	    }
   191	
   192	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
   193	    public int start(int port) {
   194	        server.start(port);
   195	        return server.port();
   196	    }
   197	
   198	    public void stop() {
   199	        server.stop();
   200	    }
   201	
   202	    public static void main(String[] args) {
   203	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
   204	        Database database = new Database(System.getenv());
   205	        new Hotel(database.dataSource()).start(port);
   206	    }
   207	}

