   150	    Message add(String channel, String to, String subject, String body) {
   151	        try (Connection connection = dataSource.getConnection();
   152	                PreparedStatement insert = connection.prepareStatement(
   153	                        "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?) RETURNING id")) {
   154	            insert.setString(1, channel);
   155	            insert.setString(2, to);
   156	            insert.setString(3, subject);
   157	            insert.setString(4, body);
   158	            try (ResultSet generated = insert.executeQuery()) {
   159	                generated.next();
   160	                return new Message(generated.getLong("id"), channel, to, subject, body);
   161	            }
   162	        } catch (SQLException failure) {
   163	            throw new IllegalStateException("could not keep the message to " + to, failure);
   164	        }
   165	    }
