   168	        try (Connection connection = dataSource.getConnection();
   169	                PreparedStatement select = connection.prepareStatement(
   170	                        "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
   171	                ResultSet rows = select.executeQuery()) {
   172	            List<Message> messages = new ArrayList<>();
   173	            while (rows.next()) {
   174	                messages.add(new Message(
   175	                        rows.getLong("id"),
   176	                        rows.getString("channel"),
   177	                        rows.getString("recipient"),
   178	                        rows.getString("subject"),
   179	                        rows.getString("body")));
   180	            }
   181	            return messages;
   182	        } catch (SQLException failure) {
   183	            throw new IllegalStateException("could not read the sent messages", failure);
   184	        }
